body .callout[data-callout*="vintage2"]  {
    --callout-icon: none;
	color: var(--lw);
	background-image: var(--gdj-vintage2);
	background-size: 100% auto;
	background-position: 50% 0%;
	background-repeat: repeat;
}

.whim-border-vintage2 {
	border-style: solid;
	border-width: 10px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-vintage2) 20;
}

.whim-border-vintage2-layer { 
	border-style: solid;
	border-width: 1px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-vintage2);
	border-image-width: auto;
	border-image-outset: 0 0 600 0;
	border-image-repeat: repeat;
}

.whim-hr-vintage2 {
	--hr-svg: var(--gdj-vintage2);
}

.whim-bg-stamp-vintage2 {
	--stamp-svg: var(--gdj-vintage2);
}

.whim-mask-vintage2 {
	-webkit-mask-image: var(--gdj-vintage2), radial-gradient(black 50%, color-mix(in srgb, black, transparent 65%) 70%, color-mix(in srgb, black, transparent 100%) 90%);
}
.whim-mask-vintage2-less {
	-webkit-mask-image: var(--gdj-vintage2), radial-gradient(black 50%, color-mix(in srgb, black, transparent 50%) 70%);
}
.whim-mask-vintage2-fade {
	-webkit-mask-image: var(--gdj-vintage2), linear-gradient(black 65%, transparent 90%);
}
.whim-mask-vintage2-fademore {
	-webkit-mask-image: var(--gdj-vintage2), linear-gradient(black 35%, transparent 65%);
}
.whim-mask-vintage2-simple {
	-webkit-mask-image: var(--gdj-vintage2), linear-gradient(color-mix(in srgb, black, transparent 25%) 25%, color-mix(in srgb, black, transparent 50%) 75%);
}